<script>const sisaBayar=<?= (int)($sisaBayar??0) ?>;const jumlahInput=document.getElementById('jumlah_bayar');const jenisInput=document.getElementById('jenis_pembayaran');function togglePembayaran(){if(jenisInput.value==='Pelunasan'){jumlahInput.value=sisaBayar;jumlahInput.readOnly=true;}else{jumlahInput.value='';jumlahInput.readOnly=false;jumlahInput.placeholder='Masukkan nominal DP';}}jenisInput.addEventListener('change',togglePembayaran);document.addEventListener('DOMContentLoaded',togglePembayaran);</script>
